/**
 * Shows a connection-quality meter: 1 to 5 coloured bars "quality<slot+1><a..e>" chosen from a ping time.
 *
 * Up to 200 ms (and outside the ranges below): 5 green bars; 200-300: 4 green; 300-400: 3 yellow; 400-500: 2 yellow;
 * over 500: 1 red. The ranges are exclusive, so exactly 300, 400 or 500 shows 5 green bars. Likely bug: a missing
 * widget leaves its slot of the local pointer array uninitialised, which is then used.
 *
 * @param screen  the cUIScreen holding the bars
 * @param slot  meter number (0-based)
 * @param ping  ping time in ms
 */
extern "C" void func_001AAD50(void* screen, int slot, int ping)
{
    if (screen == 0) {
        return;
    }
    sCol1AAD50 col(1.0f, 0.2199999988079071f, 0.5400000214576721f, 0.10000000149011612f);
    int bars = 5;
    char name[32];
    cFEVObj_001AAD50* objs[5];
    unsigned char i;
    for (i = 0; i < 5; i++) {
        sprintf(name, str_qualitypct_dpct_c, slot + 1, i + 'a');
        cFEVObj_001AAD50* barObj = (cFEVObj_001AAD50*)cUIScreen_getObjectByHashName(screen, GetHashValue32(name));
        if (barObj != 0) {
            objs[i] = barObj;
        }
    }
    if (ping > 200 && ping < 300) {
        col = sCol1AAD50(1.0f, 0.2199999988079071f, 0.5400000214576721f, 0.10000000149011612f);
        bars = 4;
    } else if (ping > 300 && ping < 400) {
        col = sCol1AAD50(1.0f, 0.949999988079071f, 0.8199999928474426f, 0.20000000298023224f);
        bars = 3;
    } else if (ping > 400 && ping < 500) {
        col = sCol1AAD50(1.0f, 0.949999988079071f, 0.8199999928474426f, 0.20000000298023224f);
        bars = 2;
    } else if (ping > 500) {
        col = sCol1AAD50(1.0f, 0.800000011920929f, 0.1599999964237213f, 0.019999999552965164f);
        bars = 1;
    }
    int j;
    for (j = 0; j < 5; j++) {
        cFEVObj_001AAD50* barObj = objs[j];
        if (j < bars) {
            barObj->setVisible(1);
            barObj->setColour(col);
        } else {
            barObj->setVisible(0);
        }
    }
}
